class JPEGSerializer(Serializer):
    """The JPEGSerializer serialize and deserialize JPEG image to and from bytes."""

    def serialize(self, item: Any) -> Tuple[bytes, Optional[str]]:
        if isinstance(item, JpegImageFile):
            if not hasattr(item, "filename"):
                raise ValueError("JPEG image does not have a filename attribute")
            if os.path.exists(item.filename):
                with open(item.filename, "rb") as f:
                    return f.read(), None
            else:
                with io.BytesIO() as f:
                    item.save(f, format="JPEG")
                    return f.getvalue(), None
        elif isinstance(item, (PngImageFile, WebPImageFile, GifImageFile, Image.Image)):
            with io.BytesIO() as f:
                item.convert("RGB").save(f, format="JPEG", quality=100)
                return f.getvalue(), None
        else:
