        dtype_indice = np.frombuffer(data[:4], np.uint32)[0]
        dtype = _TORCH_DTYPES_MAPPING[dtype_indice]
        shape_size = np.frombuffer(data[4:8], np.uint32)[0]
        shape = [np.frombuffer(data[8 + 4 * i : 8 + 4 * (i + 1)], np.uint32)[0] for i in range(shape_size)]
        start_index = 8 + 4 * shape_size
        tensor_data = data[start_index:]
        tensor = torch.frombuffer(tensor_data, dtype=dtype)
        tensor_shape = torch.Size(shape)
        if tensor.shape == tensor_shape:
            return tensor
        else:
            return torch.reshape(tensor, tensor_shape)

    def can_serialize(self, item: Any) -> bool:
        return isinstance(item, torch.Tensor)
